export function buildingModel(type,m,season=0,seed=1){const g=new T.Group();
 if(['house','hall','warehouse','forester','gatherer','woodcutter','fisher'].includes(type)){house(g,m,type,seed);}
 else if(type==='well'){const wall=new T.Mesh(new T.CylinderGeometry(.35,.38,.4,16,1,true),m.stone);wall.position.y=.2;g.add(wall);const water=new T.Mesh(new T.CircleGeometry(.32,20),m.black);water.rotation.x=-Math.PI/2;water.position.y=.08;g.add(water);for(const x of [-.4,.4])cube(g,m.darkWood,x,.55,0,.07,1.1,.07);beam(g,m.wood,[-.42,.7,0],[.42,.7,0],.04);roof(g,m,.95,.9,1.02,.32);beam(g,m.darkWood,[0,.75,0],[0,.22,0],.012);}
 else if(type==='market'){for(const x of [-.48,.48]){cube(g,m.wood,x,.25,0,.8,.5,1.35);for(const z of [-.7,.7])for(const xx of [-.38,.38])cube(g,m.darkWood,x+xx,.67,z,.04,1.35,.04);quad(g,x<0?m.fabric:m.redFabric,[[x-.45,1.12,-.8],[x-.45,1.12,.8],[x+.45,1.35,.8],[x+.45,1.35,-.8]]);for(let i=0;i<18;i++)ball(g,i%2?m.bush:m.thatch,x-.3+hash(i,1)*.6,.55,-.6+hash(i,2)*1.2,.045,.04,.045);}}
 else if(type==='farm'){cube(g,m.soil,0,.015,0,2.94,.035,2.94);fence(g,m,2.95,2.95);for(let i=0;i<12;i++)cube(g,m.dirt,-1.35+i*.245,.035,0,.04,.025,2.8);
  if(season!==3){const wheatMat=season===0?m.grass:m.thatch;for(let i=0;i<13;i++)for(let j=0;j<12;j++){const x=-1.3+i*.21,z=-1.3+j*.23,sz=season===0?.22:.42;const blades=new T.Mesh(new T.PlaneGeometry(.17,sz),season===0?m.grass:m.crop);blades.position.set(x,.04+sz/2,z);blades.rotation.y=hash(i,j)*Math.PI;g.add(blades);if(season!==0)ball(g,m.thatch,x,.04+sz,z,.025,.075,.025);}}
 }
 else if(type==='pasture'){fence(g,m,2.95,2.95);const shelter=new T.Group();cube(shelter,m.wood,0,.2,0,.7,.4,.55);roof(shelter,m,.8,.65,.4,.3,'thatch');shelter.position.set(-.95,0,-.9);g.add(shelter);for(let i=0;i<5;i++){const s=animalModel(m,'sheep');s.position.set(-.95+hash(i,1)*1.8,0,-.7+hash(i,2)*1.9);s.rotation.y=hash(i,3)*6.28;g.add(s);}}
 else if(type==='quarry'){cube(g,m.rock,0,.02,0,2.95,.05,2.95);for(let i=0;i<18;i++){const rock=new T.Mesh(new T.DodecahedronGeometry(.12+hash(i,1)*.3,0),m.rock);rock.position.set(-1.2+hash(i,2)*2.4,.15,-1.2+hash(i,3)*2.4);rock.scale.y=.5+hash(i,4);g.add(rock);}beam(g,m.darkWood,[.8,0,.8],[.8,1.8,.8],.06);beam(g,m.darkWood,[.8,1.8,.8],[-.65,1.9,.8],.045);beam(g,m.darkWood,[.8,1,.8],[-.5,1.9,.8],.025);beam(g,m.iron,[-.6,1.9,.8],[-.6,.15,.8],.009);}
 const smoke=g.userData.smoke;const result=mergeByMaterial(g);result.userData.smoke=smoke;return result;
}
export function animalModel(m,type='deer'){const g=new T.Group();const wool=type==='sheep',mat=wool?m.wool:m.wood;ball(g,mat,0,.22,0,.15,.11,.26);ball(g,wool?m.darkWood:mat,0,.3,.27,.07,.075,.105);if(!wool)beam(g,mat,[0,.2,.15],[0,.4,.24],.065);for(const x of [-.09,.09])for(const z of [-.15,.16]){const leg=cube(g,m.darkWood,x,.09,z,.028,.2,.028);}if(!wool)for(const x of [-.05,.05]){beam(g,m.wood,[x,.36,.26],[x*2,.54,.29],.01);beam(g,m.wood,[x*1.5,.45,.27],[x*3,.52,.31],.008);}return mergeByMaterial(g);}
export function citizenModel(m,color){const g=new T.Group(),shirt=new T.MeshStandardMaterial({color,roughness:1});cube(g,shirt,0,.3,0,.15,.22,.09);ball(g,m.skin,0,.47,0,.062,.07,.062);const hat=new T.Mesh(new T.CylinderGeometry(.09,.09,.025,10),m.thatch);hat.position.y=.525;g.add(hat);const crown=new T.Mesh(new T.CylinderGeometry(.055,.065,.05,8),m.thatch);crown.position.y=.56;g.add(crown);const limbs=[];for(const x of [-.045,.045]){const leg=new T.Group();leg.position.set(x,.2,0);cube(leg,m.trousers,0,-.08,0,.045,.18,.045);cube(leg,m.darkWood,0,-.17,.015,.055,.035,.075);g.add(leg);limbs.push(leg);}for(const x of [-.11,.11]){const arm=new T.Group();arm.position.set(x,.38,0);cube(arm,shirt,0,-.06,0,.045,.15,.05);ball(arm,m.skin,0,-.15,0,.026,.032,.026);g.add(arm);limbs.push(arm);}g.userData.limbs=limbs;return g;}

// Leaf cards have real alpha-cut needle / leaf textures, rather than cone crowns.
export function treeModel(m,variant=0){const g=new T.Group(),pine=variant!==2,height=pine?3.7:3.1;
 beam(g,m.bark,[0,0,0],[.04,height*.9,0],pine?.07:.105);
 // Las hojas recortadas sobre planos pueden quedarse de canto al inclinar
 // la cámara. Un núcleo de pocos polígonos da volumen desde cualquier ángulo.
 if(pine){
  const core=new T.Mesh(new T.ConeGeometry(.66,2.65,7,1),m.canopy);
  core.position.set(0,2.02,0);core.rotation.y=variant*.41;
  core.castShadow=core.receiveShadow=true;g.add(core);
 }else{
  const lobes=[[0,2.15,0,.78,.74,.78],[-.51,2.10,.19,.55,.60,.53],[.48,2.17,-.27,.57,.55,.56],[.16,2.48,.34,.54,.49,.50]];
  const geo=new T.IcosahedronGeometry(1,0);
  for(const [x,y,z,sx,sy,sz] of lobes){
   const core=new T.Mesh(geo,m.canopy);
   core.position.set(x,y,z);core.scale.set(sx,sy,sz);
   core.castShadow=core.receiveShadow=true;g.add(core);
  }
 }
 if(pine){for(let ring=0;ring<9;ring++){const y=.55+ring*.35,r=(1-ring/10)*1.02;for(let a=0;a<9;a++){const angle=a/9*Math.PI*2+ring*.79+variant*.45,dx=Math.cos(angle),dz=Math.sin(angle),len=r*(.75+hash(a,ring+variant)*.3);beam(g,m.bark,[0,y,0],[dx*len,y-.14,dz*len],.018*(1-ring/11));const right=new T.Vector3(-dz,0,dx).multiplyScalar(len*.48);const root=new T.Vector3(dx*.03,y+.1,dz*.03),tip=new T.Vector3(dx*len,y-.12,dz*len);quad(g,m.needles,[root.clone().sub(right).toArray(),tip.clone().sub(right.clone().multiplyScalar(.75)).toArray(),tip.clone().add(right.clone().multiplyScalar(.75)).toArray(),root.clone().add(right).toArray()]);const vertical=[new T.Vector3(0,y-.15,0),new T.Vector3(dx*len,y-.3,dz*len),new T.Vector3(dx*len,y+.08,dz*len),new T.Vector3(0,y+.25,0)];quad(g,m.needles,vertical.map(p=>p.toArray()));}}
 }else{for(let i=0;i<22;i++){const angle=i*2.399,y=1.2+hash(i,5)*1.6,r=.35+hash(i,6)*.65,x=Math.cos(angle)*r,z=Math.sin(angle)*r;beam(g,m.bark,[0,.7,0],[x,y,z],.03);for(let j=0;j<3;j++){const o=new T.Mesh(new T.PlaneGeometry(.85+hash(i,j)*.5,.75+hash(j,i)*.5),m.leaves);o.position.set(x,y,z);o.rotation.set(.2+hash(i,j)*.65,j/3*Math.PI+angle,hash(j,i)*.2);g.add(o);}}}
 return mergeByMaterial(g);
}

export function constructionModel(b,m){const g=new T.Group(),w=b.w-.15,h=b.h-.15;cube(g,m.stone,0,.08,0,w,.16,h);for(const x of [-w/2,w/2])for(const z of [-h/2,h/2])cube(g,m.wood,x,.48,z,.055,.96,.055);for(const z of [-h/2,h/2])cube(g,m.wood,0,.88,z,w,.045,.045);for(const x of [-w/2,w/2])beam(g,m.wood,[x,0,-h/2],[x,.9,h/2],.025);for(let i=0;i<7;i++)cube(g,m.wood,-w*.3,.17+i*.035,0,.13,.03,h*.8);return mergeByMaterial(g);}
